sys_script_client.script:
function onChange(newValue, isLoading) {
    if (isLoading || newValue === ''){
		return;
	} 

    var learningModule = g_form.getValue("learning_module");
    var date = g_form.getValue("date");

    if (!learningModule || !date) {
        return;
    }

    var ga = new GlideAjax('CheckTrainingSchedule');  
    ga.addParam('sysparm_name', 'checkSchedule'); 
    ga.addParam('sysparm_learning_module', learningModule);
    ga.addParam('sysparm_date', date);

    ga.getXMLAnswer(function(answer) {
        if (answer === 'true') {
			g_form.setValue("learning_module", "");
            g_form.setValue("date", "");
            g_form.showErrorBox("date","There is already a training scheduled for this course on the same date.", true);        
        }
    });
}
